   Prob_6_35f_Shift_Register_vhdl is   port (A_par: buffer bit_vector (3 downto 0); I_par: in bit_vector (3 downto 0);    MSB_in, LSB_in, s1, s0, CLK, Clear: in bit);    end Prob_6_35f_Shift_Register_vhdl ;      architecture Behavioral of Prob_6_35f_Shift_Register_vhdl is   begin     process (CLK, Clear) begin   	 if (Clear = '0') then A_par <= "0000";       	else case (s1 & s0) is         	when "11" =>	A_par <= I_par;         	when "01" =>	A_par <= MSB_in & A_par(3 downto 1);         	when "10" =>	A_par <= A_par (2  downto 0) & LSB_in;         	when "00" =>	A_par <= A_par;       end case;   end Behavioral;